package com.xinhe.nexus.management.service;

import com.xinhe.nexus.management.auth.ManagementUser;
import java.sql.Statement;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** ERP仓库、库存和CRM审核订单的后续履约。 */
@Service
public class ErpOperationsService {
    private final JdbcTemplate db;
    public ErpOperationsService(JdbcTemplate db){this.db=db;}

    public List<Map<String,Object>> warehouses(ManagementUser u,Boolean enabledOnly){require(u,"erp:warehouse:view");return db.queryForList("SELECT id,warehouse_code warehouseCode,warehouse_name warehouseName,address,remark,status,version FROM erp_warehouse WHERE company_id=? AND deleted_at IS NULL"+(Boolean.TRUE.equals(enabledOnly)?" AND status='ENABLED'":"")+" ORDER BY id",u.companyId());}
    @Transactional public Map<String,Object> createWarehouse(ManagementUser u,WarehouseInput in){require(u,"erp:warehouse:edit");String name=required(in.warehouseName(),"仓库名称");ensureWarehouseName(u,name,null);String code="WH-"+String.format("%04d",nextNumber(u.companyId(),"WAREHOUSE"));long id=insert("INSERT INTO erp_warehouse(company_id,warehouse_code,warehouse_name,address,remark,created_by,updated_by) VALUES(?,?,?,?,?,?,?)",u.companyId(),code,name,trim(in.address()),trim(in.remark()),u.id(),u.id());return warehouse(u,id);}
    @Transactional public Map<String,Object> updateWarehouse(ManagementUser u,long id,WarehouseInput in){require(u,"erp:warehouse:edit");String name=required(in.warehouseName(),"仓库名称");ensureWarehouseName(u,name,id);int n=db.update("UPDATE erp_warehouse SET warehouse_name=?,address=?,remark=?,version=version+1,updated_by=? WHERE company_id=? AND id=? AND deleted_at IS NULL AND version=?",name,trim(in.address()),trim(in.remark()),u.id(),u.companyId(),id,in.version()==null?-1:in.version());if(n!=1)throw new ManagementException(HttpStatus.CONFLICT,"仓库已被修改或不存在");return warehouse(u,id);}
    @Transactional public void setWarehouseStatus(ManagementUser u,long id,boolean enabled){require(u,"erp:warehouse:edit");if(!enabled){Long qty=db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM erp_inventory_balance WHERE company_id=? AND warehouse_id=?",Long.class,u.companyId(),id);if(qty!=null&&qty!=0)throw bad("仓库仍有库存，不能停用");}int n=db.update("UPDATE erp_warehouse SET status=?,version=version+1,updated_by=? WHERE company_id=? AND id=? AND deleted_at IS NULL",enabled?"ENABLED":"DISABLED",u.id(),u.companyId(),id);if(n!=1)throw new ManagementException(HttpStatus.NOT_FOUND,"仓库不存在");}
    @Transactional public void deleteWarehouse(ManagementUser u,long id){require(u,"erp:warehouse:edit");Long qty=db.queryForObject("SELECT COALESCE(SUM(quantity),0) FROM erp_inventory_balance WHERE company_id=? AND warehouse_id=?",Long.class,u.companyId(),id);Integer used=db.queryForObject("SELECT COUNT(*) FROM erp_sales_dispatch WHERE company_id=? AND warehouse_id=?",Integer.class,u.companyId(),id);if((qty!=null&&qty!=0)||(used!=null&&used>0))throw bad("仓库已有库存或业务记录，不能删除");int n=db.update("UPDATE erp_warehouse SET deleted_at=NOW(),status='DISABLED',updated_by=? WHERE company_id=? AND id=? AND deleted_at IS NULL",u.id(),u.companyId(),id);if(n!=1)throw new ManagementException(HttpStatus.NOT_FOUND,"仓库不存在");}

    public List<Map<String,Object>> inventory(ManagementUser u,Long warehouseId,String productCode,String productName){require(u,"erp:inventory:view");StringBuilder sql=new StringBuilder("SELECT b.id,b.warehouse_id warehouseId,w.warehouse_code warehouseCode,w.warehouse_name warehouseName,b.product_id productId,p.product_code productCode,p.product_name productName,p.model,p.specification,b.quantity,b.version,b.updated_at updatedAt FROM erp_inventory_balance b JOIN erp_warehouse w ON w.id=b.warehouse_id AND w.company_id=b.company_id AND w.deleted_at IS NULL JOIN erp_product p ON p.id=b.product_id AND p.company_id=b.company_id WHERE b.company_id=?");List<Object>a=new ArrayList<>();a.add(u.companyId());if(warehouseId!=null){sql.append(" AND b.warehouse_id=?");a.add(warehouseId);}like(sql,a,"p.product_code",productCode);like(sql,a,"p.product_name",productName);sql.append(" ORDER BY w.id,p.id");return db.queryForList(sql.toString(),a.toArray());}
    @Transactional public Map<String,Object> adjustInventory(ManagementUser u,InventoryAdjustment in){require(u,"erp:inventory:adjust");if(in.quantity()==null||in.quantity()<0)throw bad("库存数量必须为非负整数");ensureWarehouseEnabled(u,in.warehouseId());ensureProduct(u,in.productId());db.update("INSERT IGNORE INTO erp_inventory_balance(company_id,warehouse_id,product_id,quantity) VALUES(?,?,?,0)",u.companyId(),in.warehouseId(),in.productId());Map<String,Object> current=db.queryForMap("SELECT id,quantity FROM erp_inventory_balance WHERE company_id=? AND warehouse_id=? AND product_id=? FOR UPDATE",u.companyId(),in.warehouseId(),in.productId());long before=((Number)current.get("quantity")).longValue(),delta=in.quantity()-before;db.update("UPDATE erp_inventory_balance SET quantity=?,version=version+1 WHERE id=?",in.quantity(),current.get("id"));db.update("INSERT INTO erp_inventory_transaction(company_id,warehouse_id,product_id,transaction_type,quantity_change,balance_after,source_type,source_id,reason,operated_by) VALUES(?,?,?,'ADJUST',?,?,'MANUAL_ADJUST',NULL,?,?)",u.companyId(),in.warehouseId(),in.productId(),delta,in.quantity(),required(in.reason(),"调整原因"),u.id());return Map.of("warehouseId",in.warehouseId(),"productId",in.productId(),"quantity",in.quantity(),"quantityChange",delta);}

    public List<Map<String,Object>> salesOrders(ManagementUser u,String orderNo,String customerName,Long salespersonUserId,String status){require(u,"erp:sales-order:view");StringBuilder sql=new StringBuilder("SELECT o.id,o.order_no orderNo,o.customer_name_snapshot customerName,s.display_name salespersonName,o.total_amount totalAmount,o.fulfillment_status fulfillmentStatus,o.created_at createdAt,o.dispatched_at dispatchedAt FROM erp_sales_fulfillment_order o JOIN sys_user s ON s.id=o.salesperson_user_id WHERE o.company_id=?");List<Object>a=new ArrayList<>();a.add(u.companyId());like(sql,a,"o.order_no",orderNo);like(sql,a,"o.customer_name_snapshot",customerName);if(salespersonUserId!=null){sql.append(" AND o.salesperson_user_id=?");a.add(salespersonUserId);}if(status!=null&&!status.isBlank()){sql.append(" AND o.fulfillment_status=?");a.add(status.trim());}sql.append(" ORDER BY o.id DESC");return db.queryForList(sql.toString(),a.toArray());}
    public Map<String,Object> salesOrder(ManagementUser u,long id){require(u,"erp:sales-order:view");List<Map<String,Object>> rows=db.queryForList("SELECT o.id,o.crm_sales_order_id crmSalesOrderId,o.order_no orderNo,o.customer_name_snapshot customerName,o.phone_snapshot phone,o.shipping_address_snapshot shippingAddress,o.salesperson_user_id salespersonUserId,s.display_name salespersonName,o.fulfillment_status fulfillmentStatus,o.total_amount totalAmount,o.remark,o.dispatched_at dispatchedAt,o.signed_at signedAt,o.signed_by_name signedByName,o.sign_remark signRemark,o.completed_at completedAt,o.version FROM erp_sales_fulfillment_order o JOIN sys_user s ON s.id=o.salesperson_user_id WHERE o.company_id=? AND o.id=?",u.companyId(),id);if(rows.isEmpty())throw new ManagementException(HttpStatus.NOT_FOUND,"ERP销售订单不存在");Map<String,Object> result=rows.get(0);result.put("lines",db.queryForList("SELECT l.id,l.line_no lineNo,l.product_id productId,l.product_code_snapshot productCode,l.product_name_snapshot productName,l.category_name_snapshot categoryName,l.product_model_snapshot model,l.product_specification_snapshot specification,l.quantity,l.unit_price unitPrice,l.amount,d.dispatch_id dispatchId,w.id warehouseId,w.warehouse_name warehouseName FROM erp_sales_fulfillment_line l LEFT JOIN erp_sales_dispatch_line d ON d.company_id=l.company_id AND d.order_line_id=l.id LEFT JOIN erp_sales_dispatch sd ON sd.id=d.dispatch_id AND sd.company_id=d.company_id LEFT JOIN erp_warehouse w ON w.id=sd.warehouse_id AND w.company_id=sd.company_id WHERE l.company_id=? AND l.order_id=? ORDER BY l.line_no",u.companyId(),id));List<Map<String,Object>> dispatches=db.queryForList("SELECT d.id,d.dispatch_no dispatchNo,d.warehouse_id warehouseId,w.warehouse_name warehouseName,d.carrier,d.tracking_no trackingNo,d.remark,d.dispatched_at dispatchedAt FROM erp_sales_dispatch d JOIN erp_warehouse w ON w.id=d.warehouse_id AND w.company_id=d.company_id WHERE d.company_id=? AND d.order_id=? ORDER BY d.id",u.companyId(),id);for(Map<String,Object> dispatch:dispatches)if(dispatch.get("remark") instanceof String remark)dispatch.put("remark",SafeRichText.sanitize(remark));result.put("dispatches",dispatches);return result;}

    @Transactional public List<Map<String,Object>> dispatch(ManagementUser u,long orderId,DispatchInput input){
        require(u,"erp:sales-dispatch:confirm");
        List<Map<String,Object>> orders=db.queryForList("SELECT fulfillment_status fulfillmentStatus FROM erp_sales_fulfillment_order WHERE company_id=? AND id=? FOR UPDATE",u.companyId(),orderId);
        if(orders.isEmpty())throw new ManagementException(HttpStatus.NOT_FOUND,"ERP销售订单不存在");
        if(!"WAITING_DISPATCH".equals(orders.get(0).get("fulfillmentStatus")))throw bad("只有待出库发货订单可以操作");
        List<Map<String,Object>> lines=db.queryForList("SELECT id,product_id productId,product_name_snapshot productName,quantity FROM erp_sales_fulfillment_line WHERE company_id=? AND order_id=? ORDER BY line_no",u.companyId(),orderId);
        if(input.groups()==null||input.groups().isEmpty())throw bad("请为全部商品分配出库仓库");
        Map<Long,Map<String,Object>> byId=new HashMap<>();for(Map<String,Object> l:lines)byId.put(((Number)l.get("id")).longValue(),l);
        Set<Long> assigned=new HashSet<>(),warehouses=new HashSet<>();
        for(DispatchGroup g:input.groups()){
            if(g.warehouseId()==null||!warehouses.add(g.warehouseId()))throw bad("每个仓库只能生成一张出库发货单");
            ensureWarehouseEnabled(u,g.warehouseId());
            if(g.lineIds()==null||g.lineIds().isEmpty())throw bad("每个仓库至少选择一个商品");
            required(g.carrier(),"配送方式");required(g.trackingNo(),"物流单号");
            for(Long lineId:g.lineIds())if(!byId.containsKey(lineId)||!assigned.add(lineId))throw bad("商品分配无效或重复");
        }
        if(assigned.size()!=lines.size())throw bad("必须为订单内全部商品分配仓库，不能遗漏");
        for(DispatchGroup g:input.groups())for(Long lineId:g.lineIds()){
            Map<String,Object> line=byId.get(lineId);long product=((Number)line.get("productId")).longValue(),qty=((Number)line.get("quantity")).longValue();
            db.update("INSERT IGNORE INTO erp_inventory_balance(company_id,warehouse_id,product_id,quantity) VALUES(?,?,?,0)",u.companyId(),g.warehouseId(),product);
            Map<String,Object> balance=db.queryForMap("SELECT id,quantity FROM erp_inventory_balance WHERE company_id=? AND warehouse_id=? AND product_id=? FOR UPDATE",u.companyId(),g.warehouseId(),product);
            long before=((Number)balance.get("quantity")).longValue();
            if(before<qty){String warehouseName=db.queryForObject("SELECT warehouse_name FROM erp_warehouse WHERE company_id=? AND id=?",String.class,u.companyId(),g.warehouseId());throw bad("仓库【"+warehouseName+"】商品【"+line.get("productName")+"】库存不足，当前库存 "+before+"，需要出库 "+qty);
            }
            db.update("UPDATE erp_inventory_balance SET quantity=quantity-?,version=version+1 WHERE id=?",qty,balance.get("id"));
        }
        List<Map<String,Object>> created=new ArrayList<>();for(DispatchGroup g:input.groups()){String no="DO-"+String.format("%08d",nextNumber(u.companyId(),"SALES_DISPATCH"));String safeRemark=SafeRichText.sanitize(g.remark()),plainRemark=SafeRichText.plainText(safeRemark);long dispatchId=insert("INSERT INTO erp_sales_dispatch(company_id,order_id,warehouse_id,dispatch_no,carrier,tracking_no,remark,created_by) VALUES(?,?,?,?,?,?,?,?)",u.companyId(),orderId,g.warehouseId(),no,trim(g.carrier()),trim(g.trackingNo()),safeRemark,u.id());for(Long lineId:g.lineIds()){Map<String,Object> line=byId.get(lineId);long product=((Number)line.get("productId")).longValue(),qty=((Number)line.get("quantity")).longValue();db.update("INSERT INTO erp_sales_dispatch_line(company_id,dispatch_id,order_line_id,product_id,quantity) VALUES(?,?,?,?,?)",u.companyId(),dispatchId,lineId,product,qty);Long after=db.queryForObject("SELECT quantity FROM erp_inventory_balance WHERE company_id=? AND warehouse_id=? AND product_id=?",Long.class,u.companyId(),g.warehouseId(),product);db.update("INSERT INTO erp_inventory_transaction(company_id,warehouse_id,product_id,transaction_type,quantity_change,balance_after,source_type,source_id,reason,operated_by) VALUES(?,?,?,'SALES_DISPATCH',?,?, 'SALES_DISPATCH',?,?,?)",u.companyId(),g.warehouseId(),product,-qty,after,dispatchId,plainRemark,u.id());}created.add(Map.of("id",dispatchId,"dispatchNo",no,"warehouseId",g.warehouseId()));}db.update("UPDATE erp_sales_fulfillment_order SET fulfillment_status='DISPATCHED',dispatched_at=NOW(),version=version+1,updated_by=? WHERE company_id=? AND id=?",u.id(),u.companyId(),orderId);return created;}
    @Transactional public void sign(ManagementUser u,long id,SignInput in){require(u,"erp:sales-order:sign");int n=db.update("UPDATE erp_sales_fulfillment_order SET fulfillment_status='SIGNED',signed_at=NOW(),signed_by_name=?,sign_remark=?,version=version+1,updated_by=? WHERE company_id=? AND id=? AND fulfillment_status='DISPATCHED'",required(in.signedByName(),"签收人"),trim(in.remark()),u.id(),u.companyId(),id);if(n!=1)throw bad("只有已出库发货订单可以确认签收");}
    @Transactional public void complete(ManagementUser u,long id){require(u,"erp:sales-order:complete");int n=db.update("UPDATE erp_sales_fulfillment_order SET fulfillment_status='COMPLETED',completed_at=NOW(),version=version+1,updated_by=? WHERE company_id=? AND id=? AND fulfillment_status='SIGNED'",u.id(),u.companyId(),id);if(n!=1)throw bad("只有已签收订单可以完成");}

    private Map<String,Object> warehouse(ManagementUser u,long id){List<Map<String,Object>> rows=db.queryForList("SELECT id,warehouse_code warehouseCode,warehouse_name warehouseName,address,remark,status,version FROM erp_warehouse WHERE company_id=? AND id=? AND deleted_at IS NULL",u.companyId(),id);if(rows.isEmpty())throw new ManagementException(HttpStatus.NOT_FOUND,"仓库不存在");return rows.get(0);}
    private void ensureWarehouseName(ManagementUser u,String name,Long except){Integer n=db.queryForObject("SELECT COUNT(*) FROM erp_warehouse WHERE company_id=? AND warehouse_name=? AND deleted_at IS NULL AND (? IS NULL OR id<>?)",Integer.class,u.companyId(),name,except,except);if(n!=null&&n>0)throw bad("仓库名称已存在");}
    private void ensureWarehouseEnabled(ManagementUser u,long id){Integer n=db.queryForObject("SELECT COUNT(*) FROM erp_warehouse WHERE company_id=? AND id=? AND status='ENABLED' AND deleted_at IS NULL",Integer.class,u.companyId(),id);if(n==null||n==0)throw bad("仓库不存在或已停用");}
    private void ensureProduct(ManagementUser u,long id){Integer n=db.queryForObject("SELECT COUNT(*) FROM erp_product WHERE company_id=? AND id=? AND status='ENABLED'",Integer.class,u.companyId(),id);if(n==null||n==0)throw bad("商品不存在或已停用");}
    private long insert(String sql,Object...args){GeneratedKeyHolder key=new GeneratedKeyHolder();db.update(c->{var ps=c.prepareStatement(sql,Statement.RETURN_GENERATED_KEYS);for(int i=0;i<args.length;i++)ps.setObject(i+1,args[i]);return ps;},key);return key.getKey().longValue();}
    private long nextNumber(long companyId,String type){db.update("INSERT INTO erp_number_sequence(company_id,document_type,current_value) VALUES(?,?,1) ON DUPLICATE KEY UPDATE current_value=current_value+1",companyId,type);return db.queryForObject("SELECT current_value FROM erp_number_sequence WHERE company_id=? AND document_type=?",Long.class,companyId,type);}
    private void like(StringBuilder sql,List<Object>a,String column,String value){if(value!=null&&!value.isBlank()){sql.append(" AND ").append(column).append(" LIKE CONCAT('%',?,'%')");a.add(value.trim());}}
    private boolean admin(ManagementUser u){return u.roles().contains("COMPANY_ADMIN")||u.roles().contains("PLATFORM_ADMIN")||u.permissions().contains("*");}
    private void require(ManagementUser u,String p){if(u.companyId()==null)throw new ManagementException(HttpStatus.FORBIDDEN,"账号未关联公司");if(admin(u)||u.permissions().contains(p))return;throw new ManagementException(HttpStatus.FORBIDDEN,"没有执行该操作的权限");}
    private String required(String s,String label){if(s==null||s.isBlank())throw bad(label+"不能为空");return s.trim();}private String trim(String s){return s==null||s.isBlank()?null:s.trim();}private ManagementException bad(String m){return new ManagementException(HttpStatus.BAD_REQUEST,m);}
    public record WarehouseInput(String warehouseName,String address,String remark,Integer version){}
    public record InventoryAdjustment(long warehouseId,long productId,Long quantity,String reason){}
    public record DispatchInput(List<DispatchGroup> groups){}
    public record DispatchGroup(Long warehouseId,List<Long> lineIds,String carrier,String trackingNo,String remark){}
    public record SignInput(String signedByName,String remark){}
}
